import shlex
import subprocess
import sys
from datetime import date, datetime, timedelta
from typing import Iterable


VERSION = "commit-93cc85d16ab60ba8d646458fe0233778317b22a3"
DEFAULT_LOG_NAME_FORMAT = "d%Y_%m_%d.md"
MARKER_PLAINTEXT = b"encryption-marker:"
ROOT_SECTION = "<root section>"


class CaptainLogError(Exception):
    pass


@dataclasses.dataclass
class ParsedArgs:
    help_requested: bool = False
    config_path: str | None = None
    log_dir_path: str | None = None
    log_name_format: str | None = None
    sunday_start: bool = False
    first_line_section: bool = False
    password: str | None = None
    encrypt: bool = False
    decrypt: bool = False


@dataclasses.dataclass
class AnnualEvent:
    name: str
    month: int
    day: int


@dataclasses.dataclass
class LoadedConfig:
    config_path: pathlib.Path
    log_dir: pathlib.Path
    log_name_format: str
    sunday_start: bool
    first_line_section: bool
    password: str | None
    annual_events: list[AnnualEvent]


@dataclasses.dataclass
class LogEntry:
    day: date
    path: pathlib.Path
    text: str
    sections: set[str]
    tags: set[str]
    tags_by_section: dict[str, set[str]]


def main() -> int:
    try:
        args = parse_args(sys.argv[1:])
        if args.help_requested:
            print_help()
            return 0

        config = load_config(args)
        if args.encrypt or args.decrypt:
            run_crypto_mode(config, decrypt=args.decrypt)
            return 0

        run_tui(config)
        return 0
    except KeyboardInterrupt:
        return 0
    except CaptainLogError as exc:
        sys.stderr.write("Captain's log encountered an error: \n")
        sys.stderr.write(f" {exc}\n")
        return 1


def parse_args(argv: list[str]) -> ParsedArgs:
    parsed = ParsedArgs()
    idx = 0
    while idx < len(argv):
        arg = argv[idx]
        if arg in ("-h", "--help"):
            parsed.help_requested = True
            idx += 1
            continue
        if arg in ("-c", "--config"):
            parsed.config_path = require_option_arg(argv, idx, arg)
            idx += 2
            continue
        if arg == "--log-dir-path":
            parsed.log_dir_path = require_option_arg(argv, idx, arg)
            idx += 2
            continue
        if arg == "--log-name-format":
            parsed.log_name_format = require_option_arg(argv, idx, arg)
            idx += 2
            continue
        if arg == "--sunday-start":
            parsed.sunday_start = True
            idx += 1
            continue
        if arg == "--first-line-section":
            parsed.first_line_section = True
            idx += 1
            continue
        if arg == "--password":
            parsed.password = require_option_arg(argv, idx, arg)
            idx += 2
            continue
        if arg == "--encrypt":
            parsed.encrypt = True
            idx += 1
            continue
        if arg == "--decrypt":
            parsed.decrypt = True
            idx += 1
            continue
        if arg.startswith("-"):
            raise CaptainLogError(f"unrecognised option '{arg}'")
        raise CaptainLogError(f"unrecognised option '{arg}'")

    return parsed


def require_option_arg(argv: list[str], idx: int, option: str) -> str:
    next_idx = idx + 1
    if next_idx >= len(argv):
        raise CaptainLogError(f"the required argument for option '{option}' is missing")
    return argv[next_idx]


def print_help() -> None:
    default_config = default_config_path()
    text = (
        "Captain's Log (caps-log)! A CLI journalig tool.\n"
        f"Version: {VERSION}\n"
        "Allowed options:\n"
        "  -h [ --help ]         show this message\n"
        "  -c [ --config ] arg   override the default config file path \n"
        f"                        ({default_config})\n"
        "  --log-dir-path arg    path where log files are stored\n"
        "  --log-name-format arg format in which log entry markdown files are saved\n"
        "  --sunday-start        have the calendar display sunday as first day of the \n"
        "                        week\n"
        "  --first-line-section  override the default behaviour of ignoring sections \n"
        "                        (lines starting with `#`) in the first line of a log \n"
        "                        entry file\n"
        "  --password arg        password for encrypted log repositories or to be used \n"
        "                        with --encrypt/--decrypt\n"
        "  --encrypt             apply encryption to all logs in log dir path (needs \n"
        "                        --password)\n"
        "  --decrypt             apply decryption to all logs in log dir path (needs \n"
        "                        --password)\n"
    )
    sys.stdout.write(text)


def default_config_path() -> str:
    return str(pathlib.Path.home() / ".caps-log" / "config.ini")


def default_log_dir() -> pathlib.Path:
    return pathlib.Path.home() / ".caps-log" / "day"


def load_config(args: ParsedArgs) -> LoadedConfig:
    config_path = pathlib.Path(args.config_path or default_config_path()).expanduser()
    raw = read_config_file(config_path)
    top_level, sections = parse_ini(raw)

    log_dir = pathlib.Path(
        args.log_dir_path
        or top_level.get("log-dir-path")
        or top_level.get("log-filename-path", "")
        or str(default_log_dir())
    ).expanduser()
    if not str(log_dir):
        log_dir = default_log_dir()

    log_name_format = (
        args.log_name_format
        or top_level.get("log-name-format")
        or top_level.get("log-filename-format")
        or DEFAULT_LOG_NAME_FORMAT
    )
    password = args.password if args.password is not None else top_level.get("password")
    sunday_start = args.sunday_start or parse_bool(top_level.get("sunday-start", "false"))
    first_line_section = args.first_line_section or parse_bool(
        top_level.get("first-line-section", "false")
    )

    annual_events = parse_annual_events(sections)
    return LoadedConfig(
        config_path=config_path,
        log_dir=log_dir,
        log_name_format=log_name_format,
        sunday_start=sunday_start,
        first_line_section=first_line_section,
        password=password,
        annual_events=annual_events,
    )


def read_config_file(path: pathlib.Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except OSError:
        raise CaptainLogError(f"Failed to open file: {path}")


def parse_ini(text: str) -> tuple[dict[str, str], dict[str, dict[str, str]]]:
    top_level: dict[str, str] = {}
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            current_section = line[1:-1].strip()
            sections.setdefault(current_section, {})
            continue
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = strip_inline_comment(value.strip())
        if current_section is None:
            top_level[key] = value
        else:
            sections[current_section][key] = value
    return top_level, sections


def strip_inline_comment(value: str) -> str:
    for marker in (" #", " ;"):
        position = value.find(marker)
        if position != -1:
            return value[:position].rstrip()
    return value


def parse_bool(value: str) -> bool:
    return value.strip().lower() in {"1", "true", "yes", "on"}


def parse_annual_events(sections: dict[str, dict[str, str]]) -> list[AnnualEvent]:
    events: list[AnnualEvent] = []
    for name, values in sections.items():
        if not name.startswith("calendar-events."):
            continue
        event_name = values.get("name")
        event_date = values.get("date")
        if not event_name or not event_date:
            continue
        match = re.fullmatch(r"\s*(\d{2})\.(\d{2})\.?\s*", event_date)
        if not match:
            continue
        day = int(match.group(1))
        month = int(match.group(2))
        if 1 <= month <= 12 and 1 <= day <= 31:
            events.append(AnnualEvent(name=event_name, month=month, day=day))
    return events


