RCON = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1B, 0x36]


def derive_key(password: bytes) -> bytes:
    return hashlib.md5(password).digest()


def derive_iv(password: bytes, key: bytes) -> bytes:
    return hashlib.md5(key + password).digest()


def expand_key(key: bytes) -> list[list[int]]:
    words: list[list[int]] = [list(key[idx : idx + 4]) for idx in range(0, 16, 4)]
    for idx in range(4, 44):
        temp = words[idx - 1][:]
        if idx % 4 == 0:
            temp = sub_word(rot_word(temp))
            temp[0] ^= RCON[(idx // 4) - 1]
        words.append([words[idx - 4][pos] ^ temp[pos] for pos in range(4)])
    round_keys: list[list[int]] = []
    for round_idx in range(11):
        block: list[int] = []
        for word in words[round_idx * 4 : (round_idx + 1) * 4]:
            block.extend(word)
        round_keys.append(block)
    return round_keys


def rot_word(word: list[int]) -> list[int]:
    return word[1:] + word[:1]


def sub_word(word: list[int]) -> list[int]:
    return [SBOX[value] for value in word]


def add_round_key(state: list[int], round_key: list[int]) -> None:
    for idx in range(16):
        state[idx] ^= round_key[idx]


def sub_bytes(state: list[int]) -> None:
    for idx in range(16):
        state[idx] = SBOX[state[idx]]


def shift_rows(state: list[int]) -> None:
    rows = [
        [state[0], state[4], state[8], state[12]],
        [state[1], state[5], state[9], state[13]],
        [state[2], state[6], state[10], state[14]],
        [state[3], state[7], state[11], state[15]],
    ]
    for row_idx in range(1, 4):
        rows[row_idx] = rows[row_idx][row_idx:] + rows[row_idx][:row_idx]
    state[:] = [
        rows[0][0], rows[1][0], rows[2][0], rows[3][0],
        rows[0][1], rows[1][1], rows[2][1], rows[3][1],
        rows[0][2], rows[1][2], rows[2][2], rows[3][2],
        rows[0][3], rows[1][3], rows[2][3], rows[3][3],
    ]


def xtime(value: int) -> int:
    value <<= 1
    if value & 0x100:
        value ^= 0x11B
    return value & 0xFF


def mix_single_column(column: list[int]) -> list[int]:
    total = column[0] ^ column[1] ^ column[2] ^ column[3]
    return [
        column[0] ^ total ^ xtime(column[0] ^ column[1]),
        column[1] ^ total ^ xtime(column[1] ^ column[2]),
        column[2] ^ total ^ xtime(column[2] ^ column[3]),
        column[3] ^ total ^ xtime(column[3] ^ column[0]),
    ]


def mix_columns(state: list[int]) -> None:
    for column_idx in range(4):
        start = column_idx * 4
        state[start : start + 4] = mix_single_column(state[start : start + 4])


def aes_encrypt_block(round_keys: list[list[int]], block: bytes) -> bytes:
    state = list(block)
    add_round_key(state, round_keys[0])
    for round_idx in range(1, 10):
        sub_bytes(state)
        shift_rows(state)
        mix_columns(state)
        add_round_key(state, round_keys[round_idx])
    sub_bytes(state)
    shift_rows(state)
    add_round_key(state, round_keys[10])
    return bytes(state)


def crypt_bytes(data: bytes, password: str, decrypt: bool) -> bytes:
    password_bytes = password.encode("utf-8")
    key = derive_key(password_bytes)
    iv = derive_iv(password_bytes, key)
    round_keys = expand_key(key)
    output = bytearray()
    previous = iv
    for offset in range(0, len(data), 16):
        chunk = data[offset : offset + 16]
        stream = aes_encrypt_block(round_keys, previous)
        transformed = bytes(chunk[idx] ^ stream[idx] for idx in range(len(chunk)))
        output.extend(transformed)
        previous = chunk if decrypt else transformed
    return bytes(output)


def encrypt_bytes(data: bytes, password: str) -> bytes:
    return crypt_bytes(data, password, decrypt=False)


def decrypt_bytes(data: bytes, password: str) -> bytes:
    return crypt_bytes(data, password, decrypt=True)


def marker_path(log_dir: pathlib.Path) -> pathlib.Path:
    return log_dir / ".cle"


def is_encrypted_repo(log_dir: pathlib.Path) -> bool:
    return marker_path(log_dir).is_file()


def validate_password(log_dir: pathlib.Path, password: str) -> bool:
    marker = marker_path(log_dir)
    if not marker.exists():
        return False
    try:
        decrypted = decrypt_bytes(marker.read_bytes(), password)
    except OSError:
        return False
    return decrypted == MARKER_PLAINTEXT


def run_crypto_mode(config: LoadedConfig, decrypt: bool) -> None:
    password = config.password
    if not password:
        if decrypt:
            raise CaptainLogError("Password must be provided when decrypting logs!")
        raise CaptainLogError("Password must be provided when encrypting logs!")

    log_dir = config.log_dir
    log_dir.mkdir(parents=True, exist_ok=True)
    marker = marker_path(log_dir)

    if decrypt:
        if not marker.exists():
            raise CaptainLogError("Already applied")
    else:
        if marker.exists():
            raise CaptainLogError("Already applied")

    print("Applying crypto...")
    for file_path in iter_log_files(log_dir, config.log_name_format):
        data = file_path.read_bytes()
        transformed = decrypt_bytes(data, password) if decrypt else encrypt_bytes(data, password)
        file_path.write_bytes(transformed)

    if decrypt:
        try:
            marker.unlink()
        except FileNotFoundError:
            pass
    else:
        marker.write_bytes(encrypt_bytes(MARKER_PLAINTEXT, password))


def iter_year_dirs(log_dir: pathlib.Path) -> Iterable[pathlib.Path]:
    if not log_dir.exists():
        return []
    year_dirs: list[pathlib.Path] = []
    for child in log_dir.iterdir():
        if child.is_dir() and re.fullmatch(r"y\d{4}", child.name):
            year_dirs.append(child)
    return sorted(year_dirs)


def iter_log_files(log_dir: pathlib.Path, log_name_format: str) -> Iterable[pathlib.Path]:
    for year_dir in iter_year_dirs(log_dir):
        for file_path in sorted(path for path in year_dir.rglob("*") if path.is_file()):
            rel_name = str(file_path.relative_to(year_dir))
            if try_parse_date(rel_name, log_name_format) is not None:
                yield file_path


def try_parse_date(name: str, log_name_format: str) -> date | None:
    try:
        return datetime.strptime(name, log_name_format).date()
    except ValueError:
        return None


def load_entries(
    log_dir: pathlib.Path,
    log_name_format: str,
    first_line_section: bool,
    encrypted: bool,
    password: str | None,
) -> dict[date, LogEntry]:
    entries: dict[date, LogEntry] = {}
    for file_path in iter_log_files(log_dir, log_name_format):
        year_dir = file_path.parent
        while year_dir.parent != log_dir and year_dir.parent != year_dir:
            year_dir = year_dir.parent
        rel_name = str(file_path.relative_to(year_dir))
        day = try_parse_date(rel_name, log_name_format)
        if day is None:
            continue
        raw = file_path.read_bytes()
        if encrypted and password:
            raw = decrypt_bytes(raw, password)
        text = raw.decode("utf-8", errors="replace")
        sections, tags, tags_by_section = parse_entry(text, first_line_section)
        entries[day] = LogEntry(
            day=day,
            path=file_path,
            text=text,
            sections=sections,
            tags=tags,
            tags_by_section=tags_by_section,
        )
    return entries


def normalize_name(value: str) -> str:
    return " ".join(value.strip().lower().split())


def extract_tag(line: str) -> str | None:
    if not line.startswith("* "):
        return None
    content = line[2:].strip()
    if not content:
        return None
    if ":" in content:
        content = content.split(":", 1)[0].rstrip()
    content = re.sub(r"\s+\([^)]*\)\s*$", "", content).strip()
    normalized = normalize_name(content)
    return normalized or None


def parse_entry(
    text: str, first_line_section: bool
) -> tuple[set[str], set[str], dict[str, set[str]]]:
    sections: set[str] = set()
    tags: set[str] = set()
    tags_by_section: dict[str, set[str]] = {}
    lines = text.splitlines()
    current_section = ROOT_SECTION
    root_used = False

    for idx, line in enumerate(lines):
        stripped = line.rstrip()
        if idx == 0 and not first_line_section:
            if stripped and not stripped.startswith("# "):
                root_used = True
            continue
        if stripped.startswith("# "):
            current_section = normalize_name(stripped[2:])
            if current_section:
                sections.add(current_section)
            continue
        tag = extract_tag(stripped)
        if tag:
            tags.add(tag)
            tags_by_section.setdefault(current_section, set()).add(tag)
            if current_section == ROOT_SECTION:
                root_used = True
            continue
        if stripped and current_section == ROOT_SECTION:
            root_used = True

    if root_used:
        sections.add(ROOT_SECTION)
    return sections, tags, tags_by_section


def format_long_day(day: date) -> str:
    return day.strftime("%d. %m. %Y.")


def format_short_day(day: date) -> str:
    return day.strftime("%d. %m. %y.")


def ensure_runtime_dirs(log_dir: pathlib.Path) -> None:
    log_dir.mkdir(parents=True, exist_ok=True)
    (log_dir / "scratchpads").mkdir(parents=True, exist_ok=True)


def run_tui(config: LoadedConfig) -> None:
    encrypted = is_encrypted_repo(config.log_dir)
    password = config.password
    if encrypted:
        if password:
            if not validate_password(config.log_dir, password):
                raise CaptainLogError("Invalid password provided!")
        else:
            password = None
    elif password:
        raise CaptainLogError("Password provided for a non encrypted repository!")

    ensure_runtime_dirs(config.log_dir)
    locale.setlocale(locale.LC_ALL, "")
    app = TuiApp(config=config, repo_encrypted=encrypted, password=password)
    curses.wrapper(app.run)


class TuiApp:
    def __init__(self, config: LoadedConfig, repo_encrypted: bool, password: str | None) -> None:
        self.config = config
        self.repo_encrypted = repo_encrypted
        self.password = password
        self.today = date.today()
        self.current_year = self.today.year
        self.selected_day = self.today
        self.focus = 0
        self.selected_section: str | None = None
        self.selected_tag: str | None = None
        self.scratchpad_mode = False
        self.scratchpad_index = 0
        self.prompt_active = repo_encrypted and password is None
        self.prompt_buffer = ""
        self.entries: dict[date, LogEntry] = {}

    def run(self, stdscr: curses.window) -> None:
        self.stdscr = stdscr
        self.configure_curses()
        self.reload_entries()

        while True:
            self.draw()
            key = self.stdscr.getch()
            if key == 3:
                return
            if self.prompt_active:
                self.handle_prompt_key(key)
                continue
            self.handle_key(key)

    def configure_curses(self) -> None:
        self.stdscr.nodelay(False)
        self.stdscr.keypad(True)
        try:
            curses.curs_set(0)
        except curses.error:
            pass
        if curses.has_colors():
            curses.start_color()
            try:
                curses.use_default_colors()
            except curses.error:
                pass
            curses.init_pair(1, curses.COLOR_BLUE, -1)
            curses.init_pair(2, curses.COLOR_RED, -1)
            curses.init_pair(3, curses.COLOR_GREEN, -1)

    def reload_entries(self) -> None:
        if self.repo_encrypted and not self.password:
            self.entries = {}
        else:
            self.entries = load_entries(
                self.config.log_dir,
                self.config.log_name_format,
                self.config.first_line_section,
                encrypted=self.repo_encrypted,
                password=self.password,
            )
        self.normalize_selections()

    def normalize_selections(self) -> None:
        section_values = [value for value, _, _ in self.section_items()]
        if self.selected_section not in section_values:
            self.selected_section = None
        tag_values = [value for value, _, _ in self.tag_items()]
        if self.selected_tag not in tag_values:
            self.selected_tag = None
        if self.selected_day.year != self.current_year:
            self.selected_day = clamp_date(self.current_year, self.selected_day.month, self.selected_day.day)

    def year_entries(self) -> list[LogEntry]:
        return sorted(
            (entry for entry in self.entries.values() if entry.day.year == self.current_year),
            key=lambda entry: entry.day,
        )

    def section_items(self) -> list[tuple[str | None, str, int]]:
        counts: dict[str, int] = {}
        for entry in self.year_entries():
            if self.selected_tag and self.selected_tag not in entry.tags:
                continue
            for section in entry.sections:
                counts[section] = counts.get(section, 0) + 1
        items: list[tuple[str | None, str, int]] = [(None, "<select none>", 0)]
        for section in sorted(counts):
            items.append((section, section, counts[section]))
        return items

    def tag_items(self) -> list[tuple[str | None, str, int]]:
        counts: dict[str, int] = {}
        for entry in self.year_entries():
            tags = (
                entry.tags_by_section.get(self.selected_section, set())
                if self.selected_section
                else entry.tags
            )
            for tag in tags:
                counts[tag] = counts.get(tag, 0) + 1
        items: list[tuple[str | None, str, int]] = [(None, "<select none>", 0)]
        for tag in sorted(counts):
            items.append((tag, tag, counts[tag]))
        return items

    def matching_entry(self, day: date) -> LogEntry | None:
        entry = self.entries.get(day)
        if entry is None:
            return None
        if self.selected_section and self.selected_section not in entry.sections:
            return None
        if self.selected_tag and self.selected_tag not in entry.tags:
            return None
        return entry

    def handle_prompt_key(self, key: int) -> None:
        if key in (curses.KEY_ENTER, 10, 13):
            if validate_password(self.config.log_dir, self.prompt_buffer):
                self.password = self.prompt_buffer
                self.prompt_buffer = ""
                self.prompt_active = False
                self.reload_entries()
                return
            raise CaptainLogError("Invalid password provided!")
        if key in (curses.KEY_BACKSPACE, 127, 8):
            self.prompt_buffer = self.prompt_buffer[:-1]
            return
        if 32 <= key <= 126:
            self.prompt_buffer += chr(key)

    def handle_key(self, key: int) -> None:
        if key == curses.KEY_RESIZE:
            return
        if key == 9:
            self.focus = (self.focus + 1) % 3
            return
        if key == curses.KEY_BTAB:
            self.focus = (self.focus - 1) % 3
            return
        if key in (ord("+"), ord("=")):
            self.current_year += 1
            self.selected_day = clamp_date(self.current_year, self.selected_day.month, self.selected_day.day)
            self.normalize_selections()
            return
        if key == ord("-"):
            self.current_year -= 1
            self.selected_day = clamp_date(self.current_year, self.selected_day.month, self.selected_day.day)
            self.normalize_selections()
            return
        if key == ord("r"):
            self.reload_entries()
            return
        if key == ord("s"):
            self.scratchpad_mode = not self.scratchpad_mode
            self.scratchpad_index = 0
            return

        if self.scratchpad_mode:
            self.handle_scratchpad_key(key)
            return

        if self.focus == 0:
            self.handle_section_key(key)
        elif self.focus == 1:
            self.handle_tag_key(key)
        else:
            self.handle_calendar_key(key)

    def handle_section_key(self, key: int) -> None:
        items = self.section_items()
        current_index = index_of_value(items, self.selected_section)
        if key in (curses.KEY_DOWN, ord("j")) and current_index < len(items) - 1:
            self.selected_section = items[current_index + 1][0]
            self.normalize_selections()
            return
        if key in (curses.KEY_UP, ord("k")) and current_index > 0:
            self.selected_section = items[current_index - 1][0]
            self.normalize_selections()
            return
        if key in (curses.KEY_RIGHT, ord("l")):
            self.focus = 1

    def handle_tag_key(self, key: int) -> None:
        items = self.tag_items()
        current_index = index_of_value(items, self.selected_tag)
        if key in (curses.KEY_DOWN, ord("j")) and current_index < len(items) - 1:
            self.selected_tag = items[current_index + 1][0]
            return
        if key in (curses.KEY_UP, ord("k")) and current_index > 0:
            self.selected_tag = items[current_index - 1][0]
            return
        if key in (curses.KEY_LEFT, ord("h")):
            self.focus = 0
            return
        if key in (curses.KEY_RIGHT, ord("l")):
            self.focus = 2

    def handle_calendar_key(self, key: int) -> None:
        if key in (curses.KEY_LEFT, ord("h")):
            self.selected_day = clamp_to_year(self.selected_day - timedelta(days=1), self.current_year)
            return
        if key in (curses.KEY_RIGHT, ord("l")):
            self.selected_day = clamp_to_year(self.selected_day + timedelta(days=1), self.current_year)
            return
        if key in (curses.KEY_UP, ord("k")):
            self.selected_day = clamp_to_year(self.selected_day - timedelta(days=7), self.current_year)
            return
        if key in (curses.KEY_DOWN, ord("j")):
            self.selected_day = clamp_to_year(self.selected_day + timedelta(days=7), self.current_year)
            return
        if key in (curses.KEY_ENTER, 10, 13):
            self.open_selected_log()
            return
        if key == ord("d"):
            self.delete_selected_log()
            return
        if key == ord("h"):
            return

    def handle_scratchpad_key(self, key: int) -> None:
        pads = self.scratchpad_files()
        if key in (curses.KEY_DOWN, ord("j")) and self.scratchpad_index < len(pads) - 1:
            self.scratchpad_index += 1
            return
        if key in (curses.KEY_UP, ord("k")) and self.scratchpad_index > 0:
            self.scratchpad_index -= 1
            return
        if key in (curses.KEY_ENTER, 10, 13):
            self.open_scratchpad(pads[self.scratchpad_index])

    def scratchpad_files(self) -> list[pathlib.Path]:
        scratch_dir = self.config.log_dir / "scratchpads"
        files = sorted(path for path in scratch_dir.glob("*.md") if path.is_file())
        if files:
            return files
        return [scratch_dir / "scratchpad.md"]

    def open_scratchpad(self, path: pathlib.Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        self.launch_editor(path, encrypted=False)
        self.reload_entries()

    def open_selected_log(self) -> None:
        target = self.log_path_for_day(self.selected_day)
        target.parent.mkdir(parents=True, exist_ok=True)
        self.launch_editor(target, encrypted=self.repo_encrypted)
        self.reload_entries()

    def delete_selected_log(self) -> None:
        target = self.log_path_for_day(self.selected_day)
        try:
            target.unlink()
        except FileNotFoundError:
            return
        self.reload_entries()

    def log_path_for_day(self, day: date) -> pathlib.Path:
        year_dir = self.config.log_dir / f"y{day.year:04d}"
        rel_name = day.strftime(self.config.log_name_format)
        return year_dir / rel_name

    def launch_editor(self, path: pathlib.Path, encrypted: bool) -> None:
        editor = os.environ.get("EDITOR") or "vi"
        command = shlex.split(editor) or ["vi"]
        command.append(str(path))

        encrypted_password = self.password if encrypted else None
        if encrypted_password is None:
            self.run_subprocess(command)
            return

        existed_before = path.exists()
        if existed_before:
            ciphertext = path.read_bytes()
            plaintext = decrypt_bytes(ciphertext, encrypted_password)
            path.write_bytes(plaintext)
        try:
            self.run_subprocess(command)
        finally:
            if path.exists():
                plaintext = path.read_bytes()
                path.write_bytes(encrypt_bytes(plaintext, encrypted_password))

    def run_subprocess(self, command: list[str]) -> None:
        curses.def_prog_mode()
        curses.endwin()
        try:
            subprocess.run(command, check=False)
        finally:
            curses.reset_prog_mode()
            self.stdscr.refresh()
            try:
                curses.curs_set(0)
            except curses.error:
                pass

    def draw(self) -> None:
        self.stdscr.erase()
        height, width = self.stdscr.getmaxyx()
        if height < 12 or width < 60:
            self.safe_addstr(0, 0, "Captain's Log requires a larger terminal.", curses.A_BOLD)
            self.stdscr.refresh()
            return

        preview_height = 5
        top_height = height - preview_height - 2
        status = (
            f"Today is: {format_long_day(self.today)}  | "
            f"There are {len(self.year_entries())} log entries for year {self.current_year}."
        )
        self.centered_text(0, status, curses.A_BOLD | curses.A_UNDERLINE)

        sections_width = 21
        tags_width = 20
        calendar_x = sections_width + tags_width + 2
        calendar_width = max(20, width - calendar_x)

        self.draw_section_box(1, 0, top_height, sections_width)
        self.draw_tag_box(1, sections_width, top_height, tags_width)
        if self.scratchpad_mode:
            self.draw_scratchpad_box(1, calendar_x, top_height, calendar_width)
        else:
            self.draw_calendar_box(1, calendar_x, top_height, calendar_width)
        self.draw_preview_box(top_height + 1, 0, preview_height, width)

        if self.prompt_active:
            self.draw_password_prompt(height, width)

        self.stdscr.refresh()

    def draw_section_box(self, y: int, x: int, h: int, w: int) -> None:
        focused = not self.scratchpad_mode and self.focus == 0
        self.draw_box(y, x, h, w, "Sections", dim=not focused)
        items = self.section_items()
        selected_index = index_of_value(items, self.selected_section)
        content_width = w - 2
        for idx, (value, label, count) in enumerate(items[: h - 2]):
            text = format_menu_line(label, count, content_width)
            attr = 0
            if not focused:
                attr |= curses.A_DIM
            if idx == selected_index:
                attr |= curses.A_REVERSE if focused else curses.A_BOLD
            self.safe_addstr(y + 1 + idx, x + 1, text, attr)

    def draw_tag_box(self, y: int, x: int, h: int, w: int) -> None:
        focused = not self.scratchpad_mode and self.focus == 1
        self.draw_box(y, x, h, w, "Tags", dim=not focused)
        items = self.tag_items()
        selected_index = index_of_value(items, self.selected_tag)
        content_width = w - 2
        for idx, (value, label, count) in enumerate(items[: h - 2]):
            text = format_menu_line(label, count, content_width)
            attr = 0
            if not focused:
                attr |= curses.A_DIM
            if idx == selected_index:
                attr |= curses.A_REVERSE if focused else curses.A_BOLD
            self.safe_addstr(y + 1 + idx, x + 1, text, attr)

    def draw_calendar_box(self, y: int, x: int, h: int, w: int) -> None:
        focused = self.focus == 2
        self.draw_box(y, x, h, w, str(self.current_year), dim=not focused)
        inner_y = y + 1
        inner_x = x + 1
        inner_h = h - 2
        inner_w = w - 2
        month_w = max(14, (inner_w - 1) // 2)
        month_h = max(7, inner_h // 2)
        start_month = max(1, min(self.selected_day.month - (1 if self.selected_day.month % 2 == 0 else 0), 9))
        months = [start_month + offset for offset in range(4)]
        positions = [
            (inner_y, inner_x),
            (inner_y, inner_x + month_w + 1),
            (inner_y + month_h, inner_x),
            (inner_y + month_h, inner_x + month_w + 1),
        ]
        for month, (month_y, month_x) in zip(months, positions):
            if month_y + 6 >= y + h:
                continue
            self.draw_month(month_y, month_x, month_w, self.current_year, month, focused)

    def draw_month(self, y: int, x: int, w: int, year: int, month: int, focused: bool) -> None:
        cal = calendar.Calendar(6 if self.config.sunday_start else 0)
        name = calendar.month_name[month]
        self.safe_addstr(y, x, truncate(name, w), curses.A_BOLD if focused else curses.A_DIM)
        weekday_header = "S  M  T  W  T  F  S" if self.config.sunday_start else "M  T  W  T  F  S  S"
        self.safe_addstr(y + 1, x, truncate(weekday_header, w), curses.A_UNDERLINE if focused else curses.A_DIM)
        weeks = cal.monthdatescalendar(year, month)
        for week_index, week in enumerate(weeks[:5]):
            row_y = y + 2 + week_index
            col_x = x
            for weekday_index, current_day in enumerate(week):
                attr = 0
                if current_day.month != month:
                    attr |= curses.A_DIM
                elif current_day == self.today:
                    attr |= color_attr(2) | curses.A_BOLD
                elif any(event.month == current_day.month and event.day == current_day.day for event in self.config.annual_events):
                    attr |= color_attr(3)
                elif weekday_index >= 5 if not self.config.sunday_start else weekday_index in (0, 6):
                    attr |= color_attr(1)
                if current_day in self.entries:
                    attr |= curses.A_UNDERLINE
                if self.matching_entry(current_day):
                    attr |= curses.A_BOLD
                if focused and current_day == self.selected_day:
                    attr |= curses.A_REVERSE
                text = f"{current_day.day:2d}"
                self.safe_addstr(row_y, col_x, text, attr)
                col_x += 3

    def draw_preview_box(self, y: int, x: int, h: int, w: int) -> None:
        title = "log preview"
        if not self.scratchpad_mode:
            title = f"log preview for {format_short_day(self.selected_day)}"
        self.draw_box(y, x, h, w, title, dim=True)
        lines: list[str] = []
        if self.scratchpad_mode:
            pads = self.scratchpad_files()
            selected = pads[self.scratchpad_index]
            if selected.exists():
                lines = selected.read_text(encoding="utf-8", errors="replace").splitlines()
        else:
            entry = self.entries.get(self.selected_day)
            if entry is not None:
                lines = entry.text.splitlines()
        content_width = w - 2
        for idx, line in enumerate(lines[: h - 2]):
            attr = curses.A_DIM
            if line.startswith("#"):
                attr = curses.A_BOLD
            elif line.startswith("* "):
                attr = color_attr(1) | curses.A_BOLD
            self.safe_addstr(y + 1 + idx, x + 1, truncate(line, content_width), attr)

    def draw_scratchpad_box(self, y: int, x: int, h: int, w: int) -> None:
        self.draw_box(y, x, h, w, "Scratchpads", dim=False)
        pads = self.scratchpad_files()
        for idx, path in enumerate(pads[: h - 2]):
            name = path.name
            attr = curses.A_REVERSE if idx == self.scratchpad_index else 0
            self.safe_addstr(y + 1 + idx, x + 1, truncate(name, w - 2), attr)

    def draw_password_prompt(self, height: int, width: int) -> None:
        box_width = 31
        box_height = 7
        start_y = max(2, (height - box_height) // 2)
        start_x = max(2, (width - box_width) // 2)
        self.draw_box(start_y, start_x, box_height, box_width, "", dim=False)
        self.safe_addstr(start_y + 1, start_x + 1, "Enter password for log files:")
        self.safe_addstr(start_y + 3, start_x + 10, " " * 8, curses.A_REVERSE)
        self.safe_addstr(start_y + 4, start_x + 10, "Submit")

    def draw_box(self, y: int, x: int, h: int, w: int, title: str, dim: bool) -> None:
        if h < 2 or w < 2:
            return
        attr = curses.A_DIM if dim else 0
        top = box_top(title, w)
        bottom = "╰" + ("─" * max(0, w - 2)) + "╯"
        self.safe_addstr(y, x, top, attr)
        for row in range(1, h - 1):
            self.safe_addstr(y + row, x, "│", attr)
            self.safe_addstr(y + row, x + w - 1, "│", attr)
        self.safe_addstr(y + h - 1, x, bottom, attr)

    def centered_text(self, y: int, text: str, attr: int = 0) -> None:
        _, width = self.stdscr.getmaxyx()
        start_x = max(0, (width - len(text)) // 2)
        self.safe_addstr(y, start_x, text, attr)

    def safe_addstr(self, y: int, x: int, text: str, attr: int = 0) -> None:
        if y < 0 or x < 0:
            return
        height, width = self.stdscr.getmaxyx()
        if y >= height or x >= width:
            return
        max_len = width - x
        try:
            self.stdscr.addstr(y, x, text[:max_len], attr)
        except curses.error:
            pass


def color_attr(pair: int) -> int:
    if curses.has_colors():
        return curses.color_pair(pair)
    return 0


def box_top(title: str, width: int) -> str:
    if width <= 2:
        return "╭╮"
    title = truncate(title, max(0, width - 2))
    fill = max(0, width - 2 - len(title))
    return "╭" + title + ("─" * fill) + "╮"


def truncate(text: str, width: int) -> str:
    if width <= 0:
        return ""
    if len(text) <= width:
        return text.ljust(width)
    return text[:width]


def format_menu_line(label: str, count: int, width: int) -> str:
    if label == "<select none>":
        text = f"> {label}"
        return truncate(text, width)
    prefix = f"{count:5d} │ "
    return truncate(prefix + label, width)


def index_of_value(items: list[tuple[str | None, str, int]], value: str | None) -> int:
    for idx, (item_value, _, _) in enumerate(items):
        if item_value == value:
            return idx
    return 0


def clamp_date(year: int, month: int, day: int) -> date:
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(day, last_day))


def clamp_to_year(target: date, year: int) -> date:
    if target.year < year:
        return date(year, 1, 1)
    if target.year > year:
        return date(year, 12, 31)
    return target


